"""Splitting money between parties."""

from collections.abc import Sequence


def _plain_split(total: int, weights: Sequence[int]) -> list[int]:
    """Split `total` by `weights` using the plain largest-remainder rule."""
    scale = sum(weights)
    shares = []
    remainders = []
    assigned = 0
    for weight in weights:
        numer = total * weight
        share = numer // scale
        shares.append(share)
        remainders.append(numer % scale)
        assigned += share
    leftover = total - assigned
    order = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        shares[i] += 1
    return shares


def allocate(total: int, weights: Sequence[int], caps: Sequence[int] | None = None) -> list[int]:
    """Split `total` cents in proportion to `weights`. See README.md for the rules."""
    if total < 0:
        raise ValueError("total must not be negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not be negative")
    if sum(weights) == 0:
        raise ValueError("weights must not add up to zero")
    if caps is not None:
        if len(caps) != len(weights):
            raise ValueError("caps must have one entry per weight")
        if any(c < 0 for c in caps):
            raise ValueError("caps must not be negative")
        if sum(c for c, w in zip(caps, weights) if w > 0) < total:
            raise ValueError("caps of parties with positive weight cannot hold the total")

    if caps is None:
        return _plain_split(total, weights)

    n = len(weights)
    result = [0] * n
    fixed = [False] * n
    remaining = total
    while remaining > 0:
        open_indices = [i for i in range(n) if not fixed[i]]
        open_weights = [weights[i] for i in open_indices]
        if sum(open_weights) == 0:
            raise ValueError("caps of parties with positive weight cannot hold the total")
        shares = _plain_split(remaining, open_weights)
        over = [pos for pos, i in enumerate(open_indices) if shares[pos] > caps[i]]
        if not over:
            for pos, i in enumerate(open_indices):
                result[i] = shares[pos]
            remaining = 0
        else:
            for pos in over:
                i = open_indices[pos]
                result[i] = caps[i]
                fixed[i] = True
                remaining -= caps[i]
    return result
